entries[299354] = { ["name"] = "Condensed Life-Force", ["text"] = "Azerite Essence\nApproximately 2 procs per minute\nYour spells and abilities have a high chance to impale your target with a spike of Azerite, causing [ 660 * (1 + Versatility) * (1.25)] Fire damage." }
entries[299355] = { ["name"] = "Guardian of Azeroth", ["text"] = "Azerite Essence\nInstant 3 min cooldown\nCall upon Azeroth to summon a Guardian of Azeroth for 30 sec who impales your target with spikes of Azerite every 2.5 sec that deal [ 660 * (1 + Versatility) * (1.25)] Fire damage. Every 8 sec, the Guardian launches a volley of Azerite Spikes at its target, dealing 670 Fire damage to all nearby enemies." }
entries[299356] = { ["name"] = "Holding Crate" }
entries[299357] = { ["name"] = "Condensed Life-Force", ["text"] = "Azerite Essence\nApproximately 2 procs per minute\nYour spells and abilities have a high chance to impale your target with a spike of Azerite, causing [ 660 * (1 + Versatility) * (1.25)] Fire damage.\n\nWhen an Azerite spike deals damage, all damage you deal against that target is increased by 3% for 6 sec." }
entries[299358] = { ["name"] = "Guardian of Azeroth", ["text"] = "Azerite Essence\nInstant 3 min cooldown\nCall upon Azeroth to summon a Guardian of Azeroth for 30 sec who impales your target with spikes of Azerite every 2.5 sec that deal [ 660 * (1 + Versatility) * (1.25)] Fire damage. Every 8 sec, the Guardian launches a volley of Azerite Spikes at its target, dealing 670 Fire damage to all nearby enemies.\n\nEach time the Guardian of Azeroth casts a spell, you gain 2% Haste, stacking up to 5 times. This effect ends when the Guardian of Azeroth despawns." }
entries[299359] = { ["name"] = "Engine of Ceaseless Progress", ["text"] = "Every 2 sec, the Heart of Azeroth empowers you with 3 Haste, Mastery, or Critical Strike. After reaching 10 stacks of either Haste, Mastery, or Critical Strike, the Heart of Azeroth temporarily overcharges, doubling the effects of Engine of Ceaseless Progress for 8 sec, after which the stacks are removed.\n\nWhen you gain a stack of one of the Engine buffs, you have a 20% chance to generate a second stack." }
entries[299360] = { ["name"] = "Engine of Ceaseless Progress", ["text"] = "Instant 2 min cooldown\nCreate a field of Azerite energy at your current location for 10 sec. While standing in this area, you gain a stack of Engine of Haste, Engine of Mastery, and Engine of Critical strike every 0.5 sec.\n\nWhile inside of the Engine of Ceaseless Progress area, take 10% reduced damage." }
entries[299361] = { ["name"] = "Engine of Ceaseless Progress", ["text"] = "Every 2 sec, the Heart of Azeroth empowers you with 3 Haste, Mastery, or Critical Strike. After reaching 10 stacks of either Haste, Mastery, or Critical Strike, the Heart of Azeroth temporarily overcharges, doubling the effects of Engine of Ceaseless Progress for 8 sec, after which the stacks are removed.\n\nWhen you gain a stack of one of the Engine buffs, you have a 20% chance to generate an additional stack, and a 10% chance to gain all three Engine effects instead of a random one." }
